trigger.http:
{
  "type": "object",
  "properties": {
    "path": {
      "description": "The unique Windmill path for this trigger. Must be of the form `u/<user>/<path>` or `f/<folder>/<path>`. This is the trigger object path, not the HTTP route path.",
      "type": "string"
    },
    "script_path": {
      "description": "Path to the script or flow to execute when triggered",
      "type": "string"
    },
    "route_path": {
      "description": "The URL route path that will trigger this endpoint (e.g., 'api/myendpoint'). Must NOT start with a /.",
      "type": "string"
    },
    "workspaced_route": {
      "description": "If true, the route includes the workspace ID in the path",
      "type": "boolean"
    },
    "summary": {
      "anyOf": [
        {
          "description": "Short summary describing the purpose of this trigger",
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "description": {
      "anyOf": [
        {
          "description": "Detailed description of what this trigger does",
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "static_asset_config": {
      "anyOf": [
        {
          "description": "Configuration for serving static assets (s3 bucket, storage path, filename)",
          "type": "object",
          "properties": {
            "s3": {
              "description": "S3 bucket path for static assets",
              "type": "string"
            },
            "storage": {
              "description": "Storage path for static assets",
              "type": "string"
            },
            "filename": {
              "description": "Filename for the static asset",
              "type": "string"
            }
          },
          "required": [
            "s3"
          ],
          "additionalProperties": false
        },
        {
          "type": "null"
        }
      ]
    },
    "is_flow": {
      "description": "True if script_path points to a flow, false if it points to a script",
      "type": "boolean"
    },
    "http_method": {
      "description": "HTTP method (get, post, put, delete, patch) that triggers this endpoint",
      "type": "string",
      "enum": [
        "get",
        "post",
        "put",
        "delete",
        "patch"
      ]
    },
    "authentication_resource_path": {
      "anyOf": [
        {
          "description": "Path to the resource containing authentication configuration (for api_key, basic_http, custom_script, signature methods)",
          "type": "string"
        },
        {
          "type": "null"
        }
      ]
    },
    "is_async": {
      "description": "Deprecated, use request_type instead",
      "type": "boolean"
    },
    "request_type": {
      "description": "How the request is handled - 'sync' waits for result, 'async' returns job ID immediately, 'sync_sse' streams results via Server-Sent Events",
      "type": "string",
      "enum": [
        "sync",
        "async",
        "sync_sse"
      ]
    },
    "authentication_method": {
      "description": "How requests are authenticated - 'none' (public), 'windmill' (Windmill token), 'api_key', 'basic_http', 'custom_script', 'signature'",
      "type": "string",
      "enum": [
        "none",
        "windmill",
        "api_key",
        "basic_http",
        "custom_script",
        "signature"
      ]
    },
    "is_static_website": {
      "description": "If true, serves static files from S3/storage instead of running a script",
      "type": "boolean"
    },
    "wrap_body": {
      "description": "If true, wraps the request body in a 'body' parameter",
      "type": "boolean"
    },
    "mode": {
      "description": "job trigger mode",
      "type": "string",
      "enum": [
        "enabled",
        "disabled",
        "suspended"
      ]
    },
    "raw_string": {
      "description": "If true, passes the request body as a raw string instead of parsing as JSON",
      "type": "boolean"
    },
    "allowed_origins": {
      "anyOf": [
        {
          "description": "Origins allowed to call this route cross-origin, matched against the request's Origin header (ignoring case) and echoed back on a match. When set, the list governs both the preflight and the response, overriding any Access-Control-Allow-Origin the runnable returns via wm_headers. Use ['*'] to opt out of any restriction, including the http_route_default_allowed_origins instance setting. An empty list is not a configuration and resolves exactly as null does. When null, the instance setting applies, or Access-Control-Allow-Origin: * if it is unset. Ignored on a static website, which has no authentication of its own and so hands out public files: restricting which browsers may read them protects nothing while breaking cross-origin webfonts and fetches. A single-file static asset is not exempt, since it can carry an authentication_method.",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ]
    },
    "error_handler_path": {
      "description": "Path to a script to run when the triggered job fails. A bare path, without the script/ or flow/ prefix a schedule error handler takes; it cannot be a flow.",
      "type": "string"
    },
    "error_handler_args": {
      "description": "Arguments to pass to the error handler",
      "type": "object",
      "propertyNames": {
        "type": "string"
      },
      "additionalProperties": {}
    },
    "retry": {
      "description": "Retry configuration for failed executions",
      "type": "object",
      "properties": {
        "constant": {
          "description": "Retry with constant delay between attempts",
          "type": "object",
          "properties": {
            "attempts": {
              "description": "Number of retry attempts",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "seconds": {
              "description": "Seconds to wait between retries",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            }
          },
          "additionalProperties": false
        },
        "exponential": {
          "description": "Retry with exponential backoff: the n-th retry waits multiplier × seconds^n",
          "type": "object",
          "properties": {
            "attempts": {
              "description": "Number of retry attempts",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "multiplier": {
              "description": "Multiplier for exponential backoff",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "seconds": {
              "description": "Base of the exponential (seconds); the n-th retry waits multiplier × seconds^n, where n counts constant retries too",
              "type": "integer",
              "minimum": 1,
              "maximum": 9007199254740991
            },
            "random_factor": {
              "description": "Random jitter percentage (0-100) to avoid thundering herd",
              "type": "integer",
              "minimum": 0,
              "maximum": 100
            }
          },
          "additionalProperties": false
        },
        "retry_if": {
          "description": "Conditional retry based on error or result",
          "type": "object",
          "properties": {
            "expr": {
              "description": "JavaScript expression that returns true to retry. Has access to 'result' and 'error' variables",
              "type": "string"
            }
          },
          "required": [
            "expr"
          ],
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "permissioned_as": {
      "description": "The user or group this trigger runs as. Used during deployment to preserve the original trigger owner.",
      "type": "string"
    },
    "preserve_permissioned_as": {
      "description": "When true and the caller is a member of the 'wm_deployers' group, preserves the original permissioned_as value instead of overwriting it.",
      "type": "boolean"
    },
    "labels": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "path",
    "script_path",
    "route_path",
    "is_flow",
    "http_method",
    "authentication_method",
    "is_static_website"
  ],
  "additionalProperties": false
}

