{
  "type": "object",
  "properties": {
    "path": {
      "description": "The unique Windmill path for this trigger. Must be of the form `u/<user>/<path>` or `f/<folder>/<path>`. This is the trigger object path, not the HTTP route path.",
      "type": "string"
    },
    "script_path": {
      "description": "Path to the script or flow to execute when a message is received",
      "type": "string"
    },
    "is_flow": {
      "description": "True if script_path points to a flow, false if it points to a script",
      "type": "boolean"
    },
    "url": {
      "description": "The WebSocket URL to connect to (can be a static URL or computed by a runnable)",
      "type": "string"
    },
    "mode": {
      "description": "job trigger mode",
      "type": "string",
      "enum": [
        "enabled",
        "disabled",
        "suspended"
      ]
    },
    "filters": {
      "description": "Filters to match incoming messages (only matching messages trigger the script). Each entry is either a leaf `{key, value}` (top-level field) or `{path, value}` (dotted path into nested objects), or a group `{any_of: [...]}` / `{all_of: [...]}` / `{none_of: [...]}` nesting more entries. Entries at the top level are combined with `filter_logic`.",
      "type": "array",
      "items": {
        "description": "Either a leaf filter, matching a field of the message (parsed as JSON) against a value by equality (or superset, when the value is an object or array) — addressed by `key` for a top-level field or `path` for a dotted path into nested objects — or a group nesting sub-filters under a boolean operator (`none_of` matches when none of its sub-filters do).\n",
        "anyOf": [
          {
            "type": "object",
            "properties": {
              "key": {
                "type": "string"
              },
              "value": {}
            },
            "required": [
              "key",
              "value"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "path": {
                "description": "Dotted path into nested objects, e.g. `a.b.c`. Does not traverse arrays.",
                "type": "string"
              },
              "value": {}
            },
            "required": [
              "path",
              "value"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "any_of": {
                "type": "array",
                "items": {
                  "type": "object",
                  "propertyNames": {
                    "type": "string"
                  },
                  "additionalProperties": {}
                }
              }
            },
            "required": [
              "any_of"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "all_of": {
                "type": "array",
                "items": {
                  "type": "object",
                  "propertyNames": {
                    "type": "string"
                  },
                  "additionalProperties": {}
                }
              }
            },
            "required": [
              "all_of"
            ],
            "additionalProperties": false
          },
          {
            "type": "object",
            "properties": {
              "none_of": {
                "type": "array",
                "items": {
                  "type": "object",
                  "propertyNames": {
                    "type": "string"
                  },
                  "additionalProperties": {}
                }
              }
            },
            "required": [
              "none_of"
            ],
            "additionalProperties": false
          }
        ]
      }
    },
    "filter_logic": {
      "default": "and",
      "description": "Logic to apply when evaluating the top-level filters. 'and' requires all of them to match, 'or' requires any of them to match. Nested `any_of`/`all_of`/`none_of` groups carry their own logic.",
      "type": "string",
      "enum": [
        "and",
        "or"
      ]
    },
    "initial_messages": {
      "anyOf": [
        {
          "description": "Messages to send immediately after connecting (can be raw strings or computed by runnables)",
          "type": "array",
          "items": {
            "anyOf": [
              {
                "type": "object",
                "properties": {
                  "raw_message": {
                    "type": "string"
                  }
                },
                "required": [
                  "raw_message"
                ],
                "additionalProperties": false
              },
              {
                "type": "object",
                "properties": {
                  "runnable_result": {
                    "type": "object",
                    "properties": {
                      "path": {
                        "type": "string"
                      },
                      "args": {
                        "description": "The arguments to pass to the script or flow",
                        "type": "object",
                        "propertyNames": {
                          "type": "string"
                        },
                        "additionalProperties": {}
                      },
                      "is_flow": {
                        "type": "boolean"
                      }
                    },
                    "required": [
                      "path",
                      "args",
                      "is_flow"
                    ],
                    "additionalProperties": false
                  }
                },
                "required": [
                  "runnable_result"
                ],
                "additionalProperties": false
              }
            ]
          }
        },
        {
          "type": "null"
        }
      ]
    },
    "url_runnable_args": {
      "anyOf": [
        {
          "description": "Arguments to pass to the script/flow that computes the WebSocket URL",
          "type": "object",
          "propertyNames": {
            "type": "string"
          },
          "additionalProperties": {}
        },
        {
          "type": "null"
        }
      ]
    },
    "can_return_message": {
      "description": "If true, the script can return a message to send back through the WebSocket",
      "type": "boolean"
    },
    "can_return_error_result": {
      "description": "If true, error results are sent back through the WebSocket",
      "type": "boolean"
    },
    "heartbeat": {
      "anyOf": [
        {
          "description": "Optional periodic heartbeat message configuration",
          "type": "object",
          "properties": {
            "interval_secs": {
              "description": "Interval in seconds between heartbeat messages",
              "type": "integer",
              "minimum": 1,
              "maximum": 9007199254740991
            },
            "message": {
              "description": "Message to send as heartbeat. Use {{state}} as a placeholder for a value extracted from incoming messages (see state_field).",
              "type": "string"
            },
            "state_field": {
              "description": "Optional. Top-level JSON field to extract from incoming messages. The extracted value replaces {{state}} in the heartbeat message.",
              "type": "string"
            }
          },
          "required": [
            "interval_secs",
            "message"
          ],
          "additionalProperties": false
        },
        {
          "type": "null"
        }
      ]
    },
    "error_handler_path": {
      "description": "Path to a script to run when the triggered job fails. A bare path, without the script/ or flow/ prefix a schedule error handler takes; it cannot be a flow.",
      "type": "string"
    },
    "error_handler_args": {
      "description": "Arguments to pass to the error handler",
      "type": "object",
      "propertyNames": {
        "type": "string"
      },
      "additionalProperties": {}
    },
    "retry": {
      "description": "Retry configuration for failed executions",
      "type": "object",
      "properties": {
        "constant": {
          "description": "Retry with constant delay between attempts",
          "type": "object",
          "properties": {
            "attempts": {
              "description": "Number of retry attempts",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "seconds": {
              "description": "Seconds to wait between retries",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            }
          },
          "additionalProperties": false
        },
        "exponential": {
          "description": "Retry with exponential backoff: the n-th retry waits multiplier × seconds^n",
          "type": "object",
          "properties": {
            "attempts": {
              "description": "Number of retry attempts",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "multiplier": {
              "description": "Multiplier for exponential backoff",
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "seconds": {
              "description": "Base of the exponential (seconds); the n-th retry waits multiplier × seconds^n, where n counts constant retries too",
              "type": "integer",
              "minimum": 1,
              "maximum": 9007199254740991
            },
            "random_factor": {
              "description": "Random jitter percentage (0-100) to avoid thundering herd",
              "type": "integer",
              "minimum": 0,
              "maximum": 100
            }
          },
          "additionalProperties": false
        },
        "retry_if": {
          "description": "Conditional retry based on error or result",
          "type": "object",
          "properties": {
            "expr": {
              "description": "JavaScript expression that returns true to retry. Has access to 'result' and 'error' variables",
              "type": "string"
            }
          },
          "required": [
            "expr"
          ],
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "permissioned_as": {
      "description": "The user or group this trigger runs as. Used during deployment to preserve the original trigger owner.",
      "type": "string"
    },
    "preserve_permissioned_as": {
      "description": "When true and the caller is a member of the 'wm_deployers' group, preserves the original permissioned_as value instead of overwriting it.",
      "type": "boolean"
    },
    "labels": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "path",
    "script_path",
    "is_flow",
    "url",
    "filters",
    "can_return_message",
    "can_return_error_result"
  ],
  "additionalProperties": false
}

